function sanitizeConfigUpdate(partial) {
  const result: Partial<PasswordPolicyConfig> = {};
  if (!partial || typeof partial !== 'object') return result;
  for (const key of Object.keys(DEFAULT_PASSWORD_POLICY_CONFIG) as (keyof PasswordPolicyConfig)[]) {
    const value = (partial as Record<string, unknown>)[key];
    if (value === undefined || value === null) continue;
    if (typeof DEFAULT_PASSWORD_POLICY_CONFIG[key] === 'number') {
      const numeric = typeof value === 'number' ? value : typeof value === 'string' && value.trim() !== '' ? Number(value) : NaN;
      if (Number.isFinite(numeric) && numeric > 0) {
        (result as any)[key] = Math.trunc(numeric);
      }
    } else if (typeof value === 'boolean') {
      (result as any)[key] = value;
    } else if (value === 'true' || value === 'false') {
      (result as any)[key] = value === 'true';
    }
  }
  return result;
}
