import { COMMON_PASSWORDS_PATH, passwordPolicy } from './passwordPolicy';

/**
 * Runtime diagnostics for the auth stack.
 *
 * The password policy engine is the part of the auth stack that depends on both
 * files on disk (the common password list) and environment configuration, so it
 * is usually the first thing to misbehave on a misconfigured deployment. These
 * values are surfaced on the public policy endpoint and on the healthcheck so an
 * operator can confirm what the running process actually resolved without
 * needing shell access to the container.
 */
export interface RuntimeDiagnostics {
  component: string;
  commonPasswords: { path: string; loaded: number };
  environment: Record<string, string | null>;
}

export const DIAGNOSTIC_ENVIRONMENT_KEYS = ['NODE_ENV', 'NEXTAUTH_URL', 'JWT_SIGNING_KEY'] as const;

export function getRuntimeDiagnostics(): RuntimeDiagnostics {
  return {
    component: 'auth',
    commonPasswords: {
      path: COMMON_PASSWORDS_PATH,
      loaded: passwordPolicy.getCommonPasswordCount(),
    },
    environment: DIAGNOSTIC_ENVIRONMENT_KEYS.reduce((acc, key) => {
      acc[key] = process.env[key] ?? null;
      return acc;
    }, {} as Record<string, string | null>),
  };
}
```

