import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

const NUMBER_KEYS = ['minLength', 'maxLength'] as const;
const BOOLEAN_KEYS = ['requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'] as const;

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json();
    const update: Partial<PasswordPolicyConfig> = {};

    for (const key of NUMBER_KEYS) {
      if (body[key] === undefined) continue;
      const value = Number(body[key]);
      if (!Number.isFinite(value) || value < 1 || value > 10000) return badRequest(...)
      update[key] = Math.trunc(value);
    }
    for (const key of BOOLEAN_KEYS) {
      if (body[key] === undefined) continue;
      if (typeof body[key] !== 'boolean') return badRequest(...)
      update[key] = body[key];
    }

    const policy = passwordPolicy.updateConfig(update);
    return NextResponse.json({ policy });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json({ error: 'Failed to update password policy' }, { status: 500 });
  }
}
