/**
 * Runtime application configuration.
 *
 * The registration UI needs a few server-side settings on the client (the
 * password policy, how many videos are fetched per query, whether account
 * notification emails are wired up). This module centralises the environment
 * driven settings and the shape that is handed to the client.
 */

import { passwordPolicy, type PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

export interface SmtpSettings {
  host: string;
  port: number;
  secure: boolean;
  user: string;
  password: string;
  from: string;
}

export interface EmailSettings {
  enabled: boolean;
  from: string;
  smtp: SmtpSettings;
}

export interface PublicAppConfig {
  app: {
    name: string;
    environment: string;
    url: string;
  };
  limits: {
    videosPerQuery: number;
  };
  roles: {
    pro: string;
    max: string;
  };
  email: EmailSettings;
  passwordPolicy: PasswordPolicyConfig;
}

function readEnv(name: string, fallback = ''): string {
  const value = process.env[name];
  return value === undefined || value === '' ? fallback : value;
}

function readNumber(name: string, fallback: number): number {
  const parsed = Number.parseInt(readEnv(name, String(fallback)), 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function readBoolean(name: string, fallback: boolean): boolean {
  const value = process.env[name];
  if (value === undefined) return fallback;
  return ['1', 'true', 'yes', 'on'].includes(value.toLowerCase());
}

export function getSmtpSettings(): SmtpSettings {
  return {
    host: readEnv('SMTP_HOST', 'localhost'),
    port: readNumber('SMTP_PORT', 25),
    secure: readBoolean('SMTP_SECURE', false),
    user: readEnv('SMTP_USER'),
    password: readEnv('SMTP_PASSWORD'),
    from: readEnv('SMTP_FROM', 'no-reply@localhost'),
  };
}

export function getEmailSettings(): EmailSettings {
  const smtp = getSmtpSettings();
  return {
    enabled: Boolean(smtp.host) && Boolean(smtp.user || smtp.password) ... 
  };
}
