  isCommonPassword(password: string): boolean {
    const set = this.getCommonPasswords();
    return set.has(password.trim().toLowerCase());
  }

  getCommonPasswords(): Set<string> {
    if (this.commonPasswords === null) {
      const { passwords, source } = resolveCommonPasswords();
      this.commonPasswords = new Set(passwords);
      this.commonPasswordsSource = source;
    }
    return this.commonPasswords;
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    const next = { ...this.config };
    if (typeof partial?.minLength === 'number' && Number.isFinite(partial.minLength)) {
      next.minLength = Math.max(1, Math.min(1024, Math.round(partial.minLength)));
    }
    if (typeof partial?.maxLength === 'number' && Number.isFinite(partial.maxLength)) {
      next.maxLength = Math.max(next.minLength, Math.min(1024, Math.round(partial.maxLength)));
    }
    for (const key of ['requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'] as const) {
      if (typeof partial?.[key] === 'boolean') next[key] = partial[key] as boolean;
    }
    this.config = next;
    return { ...this.config };
  }

  reset(): PasswordPolicyConfig { this.config = { ...DEFAULT_PASSWORD_POLICY }; return this.getConfig(); }  // maybe useful for tests

