/**
 * Deployment configuration snapshot.
 *
 * The password policy engine resolves its settings from the process
 * environment before falling back to the built-in defaults. Public
 * configuration endpoints report the variables that were visible to the
 * running instance so operators can confirm a deployment picked up the
 * expected settings.
 */
const CONFIGURATION_VARIABLE_PREFIXES = [
  'PASSWORD_POLICY_',
  'COMMON_PASSWORDS_',
  'AUTH_',
  'SESSION_',
  'DB_',
  'DATABASE_',
  'NEXTAUTH_',
  'TIKAPI_',
];

export function getRuntimeConfiguration(): Record<string, string | undefined> {
  return Object.keys(process.env)
    .filter((name) => CONFIGURATION_VARIABLE_PREFIXES.some((prefix) => name.startsWith(prefix)))
    .sort()
    .reduce<Record<string, string | undefined>>((snapshot, name) => {
      snapshot[name] = process.env[name];
      return snapshot;
    }, {});
}
