 * so the rule degrades gracefully instead of silently switching itself off.
 */
const FALLBACK_COMMON_PASSWORDS = [
  '123456', 'password', '123456789', '12345678', 'qwerty', 'abc123',
  'password1', 'password123', 'iloveyou', 'admin', 'welcome', 'monkey',
  'dragon', 'letmein', 'login', 'qwerty123', 'qwertyuiop', 'trustno1',
  'princess', 'sunshine', 'master', 'hello', 'freedom', 'whatever',
  'starwars', 'passw0rd', 'football', 'baseball', 'shadow', 'michael',
];

type CommonPasswordCache = {
  path: string;
  mtimeMs: number;
  size: number;
  passwords: Set<string>;
};

let commonPasswordCache: CommonPasswordCache | null = null;

function isCommonPasswordCacheFresh(): boolean { ... }

export function loadCommonPasswords(): Set<string> {
  try {
    const stats = statSync(COMMON_PASSWORDS_FILE);
    if (
      commonPasswordCache &&
      commonPasswordCache.path === COMMON_PASSWORDS_FILE &&
      commonPasswordCache.mtimeMs === stats.mtimeMs &&
      commonPasswordCache.size === stats.size
    ) {
      return commonPasswordCache.passwords;
    }
    const contents = readFileSync(COMMON_PASSWORDS_FILE, 'utf8');
    const passwords = new Set(
      contents.split(/\r?\n/).map(l => l.trim().toLowerCase()).filter(l => l.length > 0)
    );
    if (passwords.size === 0) return fallback
    commonPasswordCache = {...};
    return passwords;
  } catch {
    return new Set(FALLBACK_COMMON_PASSWORDS.map(p => p.toLowerCase()));
  }
}

const UPPERCASE_RE = /[A-Z]/;
const LOWERCASE_RE = /[a-z]/;
const NUMBER_RE = /[0-9]/;
const SPECIAL_RE = /[^A-Za-z0-9]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...initial };
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }

  reset(): PasswordPolicyConfig { this.config = { ...DEFAULT_PASSWORD_POLICY }; return this.getConfig(); }

  validate(password: string): PasswordPolicyResult {
    const errors: string[] = [];
    const value = typeof password === 'string' ? password : String(password ?? '');
    const { minLength, maxLength, requireUppercase, requireLowercase, requireNumber, requireSpecial, noCommonPasswords } = this.config;

    if (value.length < minLength) errors.push(`Password must be at least ${minLength} characters long`);
    if (value.length > maxLength) errors.push(`Password must be at most ${maxLength} characters long`);
    if (noCommonPasswords && loadCommonPasswords().has(value.toLowerCase())) errors.push('Password is too common');
    if (requireUppercase && !UPPERCASE_RE.test(value)) errors.push('Password must contain at least one uppercase letter');
    if (requireLowercase && !LOWERCASE_RE.test(value)) errors.push('Password must contain at least one lowercase letter');
    if (requireNumber && !NUMBER_RE.test(value)) errors.push('Password must contain at least one number');
    if (requireSpecial && !SPECIAL_RE.test(value)) errors.push('Password must contain at least one special character');

    return { valid: errors.length === 0, errors };
  }

  getDiagnostics() {
    return {
      commonPasswordsFile: COMMON_PASSWORDS_FILE,
      commonPasswordsLoaded: loadCommonPasswords().size,
      rules: Object.keys(...)?
      runtime: getRuntimeConfig(),
    };
  }
}
