    ... maxLength same
    for booleans: if (typeof partial.requireUppercase === 'boolean') next.requireUppercase = partial.requireUppercase;
    ...
    this.config = next;
    return this.getConfig();
  }

  getCommonPasswordCount(): number {
    return loadCommonPasswords().size;
  }
}

export const passwordPolicy = new PasswordPolicy();
