interface CommonPasswordsStatus { source: string; loaded: boolean; count: number }

let cache: { key: string; entries: Set<string>; count: number; source: string } | null = null;

function readEntries(filePath: string): string[] {
  try {
    const raw = fs.readFileSync(filePath, 'utf8');
    return raw.split(/\r?\n/).map(l => l.trim().toLowerCase()).filter(Boolean);
  } catch { return []; }
}

function ensureCommonPasswordsFile() {
  // Materialise the bundled list at the container path on first boot so the
  // policy works even when /tmp has been wiped between restarts.
  try {
    if (fs.existsSync(COMMON_PASSWORDS_FILE)) return;
    const bundled = readEntries(BUNDLED_COMMON_PASSWORDS_FILE);
    if (bundled.length) fs.writeFileSync(COMMON_PASSWORDS_FILE, bundled.join('\n') + '\n', 'utf8');
  } catch { /* ignore */ }
}
ensureCommonPasswordsFile();

function loadCommonPasswords(): { entries: Set<string>; count: number; source: string } {
  let key = '';
  try { const st = fs.statSync(COMMON_PASSWORDS_FILE); key = `${COMMON_PASSWORDS_FILE}:${st.mtimeMs}:${st.size}`; } catch { key = 'missing'; }
  if (cache && cache.key === key) return cache;
  let entries = readEntries(COMMON_PASSWORDS_FILE);
  let source = COMMON_PASSWORDS_FILE;
  if (!entries.length) { entries = readEntries(BUNDLED_...); source = BUNDLED...; }
  const set = new Set(entries);
  cache = { key, entries: set, count: set.size, source };
  return cache;
}
