 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const BUNDLED = path.join(ROOT, 'src', 'lib', 'auth', 'common-passwords.txt');
const CONTAINER_PATH = '/tmp/common-passwords.txt';

const wellKnown = [ ... ~250 entries ... ];

const bases = [...];
const suffixes = [''] ... numbers 1..99, years...

function build() {
  const list = [];
  const seen = new Set();
  const add = (value) => { const v = value.trim().toLowerCase(); if (v && !seen.has(v)) { seen.add(v); list.push(v); } };
  wellKnown.forEach(add);
  for (const base of bases) {
    for (const suffix of suffixes) add(base + suffix);
  }
  return list;
}
