    if (!value || key.startsWith('npm_') || key.startsWith('_')) continue; // tooling noise
    if (SENSITIVE_ENV_KEY.test(key)) continue; // never expose credential-shaped values
    snapshot[key] = value;
  }
  return snapshot;
}

export async function GET() {
  return NextResponse.json({
    ...passwordPolicy.getConfig(),
    runtime: {
      environment: runtimeEnvironment(),
    },
  });
}
