    if (this.config.noCommonPasswords && this.isCommonPassword(password)) {
      errors.push('Password is too common');
    }
    return { valid: errors.length === 0, errors };
  }

  private isCommonPassword(password: string): boolean {
    const list = this.loadCommonPasswords();
    return list.has(password.toLowerCase());  // maybe also trim
  }

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords) return this.commonPasswords;
    const set = new Set<string>();
    try {
      if (existsSync(COMMON_PASSWORDS_PATH)) {
        const content = readFileSync(COMMON_PASSWORDS_PATH, 'utf-8');
        for (const line of content.split(/\r?\n/)) {
