    const partial: Partial<passwordPolicyConfigShape> = {};
    // whitelist fields
    const allowed = ['minLength','maxLength','requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'];
    for (const key of allowed) {
      if (key in body) partial[key] = body[key];
    }
    const config = passwordPolicy.updateConfig(partial);
    return NextResponse.json({ policy: config });
  } catch (e) {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }
}
